package ru.personal.alfafinance;
import android.app.*; import android.os.*; import android.content.*; import android.graphics.Color; import android.view.*; import android.widget.*; import org.json.*; import java.time.*; import java.math.*; import java.io.*; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; android.content.SharedPreferences prefs; JSONArray rows=new JSONArray(); String month; long budget; final int RED=0xffd92532;
 public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(0xff202124); getWindow().setNavigationBarColor(0xff202124); getWindow().setFlags(8192,8192); prefs=getSharedPreferences("local",0); try{rows=new JSONArray(prefs.getString("rows","[]"));}catch(Exception e){} month=YearMonth.now().toString(); show();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} void save(){prefs.edit().putString("rows",rows.toString()).apply();} String money(long n){return String.format(new Locale("ru","RU"),"%,.2f ₽",BigDecimal.valueOf(n,2));} long parse(String s){return new BigDecimal(s.trim().replace(" ","").replace("\u00a0","").replace(',','.')).movePointRight(2).longValueExact();}
 void txt(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff202124);t.setPadding(0,dp(8),0,dp(8));root.addView(t);} void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());root.addView(b);}
 long[] totals(){long in=0,out=0; for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&r.optString("date").startsWith(month)){long a=r.optLong("amount");if(a>0)in+=a;else out-=a;}}return new long[]{in,out};}
 void show(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(28),dp(20),dp(28));sc.addView(root);setContentView(sc); budget=prefs.getLong("budget_"+month,0);long[] t=totals();txt("Альфа-банка",30);txt("Личный финансовый помощник • неофициальный",14);txt("Месяц: "+month,20);btn("Предыдущий месяц",()->{month=YearMonth.parse(month).minusMonths(1).toString();show();});btn("Следующий месяц",()->{month=YearMonth.parse(month).plusMonths(1).toString();show();});txt("Доходы: "+money(t[0])+"\nРасходы: "+money(t[1])+"\nРазница: "+money(t[0]-t[1]),22);txt("Бюджет: "+(budget>0?money(budget):"не задан")+(budget>0?"\nОстаток лимита: "+money(budget-t[1]):""),20);btn("Настроить бюджет",()->budgetDialog());btn("Добавить операцию",()->addDialog());btn("Импорт CSV",()->{Intent it=new Intent(Intent.ACTION_OPEN_DOCUMENT);it.setType("*/*");it.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(it,7);});btn("Финансовый помощник (локальные правила)",()->advice());txt("Банк не подключён. Данные только из импорта и ручного ввода.",14);txt("Операции",22);for(int i=rows.length()-1;i>=0;i--){JSONObject r=rows.optJSONObject(i);if(r==null||!r.optString("date").startsWith(month))continue;final int idx=i;btn(r.optString("date")+" • "+r.optString("category")+"\n"+r.optString("description")+" • "+money(r.optLong("amount")),()->new AlertDialog.Builder(this).setMessage("Удалить операцию?").setNegativeButton("Нет",null).setPositiveButton("Удалить",(d,w)->{rows.remove(idx);save();show();}).show());}}
 EditText field(LinearLayout l,String hint,String val){EditText e=new EditText(this);e.setHint(hint);e.setText(val);e.setSingleLine();l.addView(e);return e;} LinearLayout panel(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(20),0,dp(20),0);return l;} void error(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void budgetDialog(){LinearLayout l=panel();EditText e=field(l,"Лимит расходов в рублях",budget==0?"":BigDecimal.valueOf(budget,2).toPlainString());new AlertDialog.Builder(this).setTitle("Бюджет на "+month).setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{try{long n=parse(e.getText().toString());if(n<0)throw new Exception();prefs.edit().putLong("budget_"+month,n).apply();show();}catch(Exception x){error("Некорректная сумма");}}).show();}
 JSONObject row(String date,long a,String cat,String desc)throws Exception{LocalDate.parse(date);if(a==0||a==Long.MIN_VALUE)throw new Exception();JSONObject r=new JSONObject();r.put("date",date);r.put("amount",a);r.put("category",cat);r.put("description",desc);return r;}
 void addDialog(){LinearLayout l=panel();EditText date=field(l,"ГГГГ-ММ-ДД",LocalDate.now().toString()),a=field(l,"Сумма: минус расход, плюс доход",""),cat=field(l,"Категория (необязательно)",""),desc=field(l,"Описание","");new AlertDialog.Builder(this).setTitle("Новая операция").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Добавить",(d,w)->{try{String s=desc.getText().toString();long n=parse(a.getText().toString());String c=cat.getText().toString();rows.put(row(date.getText().toString(),n,c.isEmpty()?category(s,n):c,s));save();show();}catch(Exception x){error("Проверьте дату и сумму");}}).show();}
 String category(String s,long n){s=s.toLowerCase(new Locale("ru"));if(n>0)return "Доход";if(s.matches(".*(пятёроч|пятероч|магнит|перекрёст|продукт).*"))return "Продукты";if(s.matches(".*(такси|метро|азс|транспорт).*"))return "Транспорт";if(s.matches(".*(аптек|здоров).*"))return "Здоровье";return "Прочее";}
 void advice(){long[] t=totals();String s="Учтено за месяц: "+money(t[1])+" расходов. ";if(budget==0)s+="Задайте лимит расходов.";else if(t[1]>budget)s+="Лимит превышен на "+money(t[1]-budget)+". Проверьте необязательные покупки.";else {s+="Остаток лимита: "+money(budget-t[1])+". ";if(month.equals(YearMonth.now().toString()))s+="На оставшиеся дни, включая сегодня: около "+money((budget-t[1])/(LocalDate.now().lengthOfMonth()-LocalDate.now().getDayOfMonth()+1))+" в день.";}new AlertDialog.Builder(this).setTitle("Финансовый помощник").setMessage(s+"\n\nЭто расчёт по внесённым данным, не остаток банковского счёта и не генеративный ИИ.").setPositiveButton("ОК",null).show();}
 protected void onActivityResult(int rq,int rc,Intent data){super.onActivityResult(rq,rc,data);if(rq!=7||rc!=RESULT_OK||data==null)return;try(BufferedReader b=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(data.getData()),java.nio.charset.StandardCharsets.UTF_8))){String h=b.readLine();if(h==null||!h.replace("\ufeff","").equals("date;amount;description"))throw new Exception("Нужен CSV: date;amount;description");JSONArray pending=new JSONArray();String line;while((line=b.readLine())!=null){if(line.trim().isEmpty())continue;String[] p=line.split(";",3);if(p.length!=3)throw new Exception("Неверная строка CSV");long n=parse(p[1]);pending.put(row(p[0],n,category(p[2],n),p[2]));if(pending.length()>20000)throw new Exception("Слишком много строк");}new AlertDialog.Builder(this).setTitle("Импорт: "+pending.length()+" операций").setMessage("Повторный импорт создаёт дубликаты. Продолжить?").setNegativeButton("Отмена",null).setPositiveButton("Импортировать",(d,w)->{for(int i=0;i<pending.length();i++)rows.put(pending.optJSONObject(i));save();show();}).show();}catch(Exception e){error("Импорт не выполнен: "+e.getMessage());}}
}
